import json,urllib.request,datetime,socket
base='http://127.0.0.1:17448'
def get(path):
 try:
  with urllib.request.urlopen(base+path,timeout=7) as r:
   return {'http':r.status,'body':json.load(r)}
 except Exception as e:
  return {'error':type(e).__name__+': '+str(e)[:130]}
ch=get('/api/supervisor-watchdog/managed-chats')
ass=get('/api/supervisor-watchdog/agent-assignments')
checks={}
for p in ['/api/health','/api/supervisor-watchdog/status']:
 x=get(p)
 checks[p]={'http':x.get('http'),'error':x.get('error'),'keys':list(x.get('body',{}).keys())[:20] if isinstance(x.get('body'),dict) else []}
cs=ch.get('body',{}).get('chats',[]) if isinstance(ch.get('body'),dict) else []
aa=ass.get('body',{}).get('assignments',[]) if isinstance(ass.get('body'),dict) else []
br=[a for a in aa if a.get('targetChatId')=='chat-6ac45836-87a0-83ed-bea4-0ad0f99c8982']
out={'checkedAt':datetime.datetime.now().isoformat(),'tcp_port_17448':None,'endpoints':checks,'chats':[{k:v.get(k) for k in ('name','status','error','highMode','generating','openTabs','lastSeenAt')} for v in cs],'bridgeAssignments':[{k:v.get(k) for k in ('id','state','dispatchCount','dispatchSubmitAttempted','lastDiagnostic','lastPreflightReason','currentHead','ciConclusion')} for v in br[-8:]],'apiErrors':{'chats':ch.get('error'),'assignments':ass.get('error')}}
s=socket.socket();s.settimeout(2)
try:s.connect(('127.0.0.1',17448));out['tcp_port_17448']='listening'
except Exception as e:out['tcp_port_17448']=type(e).__name__
finally:s.close()
print(json.dumps(out,ensure_ascii=True,separators=(',',':')))
